function limparChaves(obj) {
  const novo = {};

  for (const chave of Object.keys(obj)) {
    const chaveLimpa = chave.trim();
    novo[chaveLimpa] = obj[chave];
  }

  return novo;
}

function numero(valor) {
  if (valor === undefined || valor === null || valor === '') return 0;

  if (typeof valor === 'number') return valor;

  const texto = String(valor)
    .replace('R$', '')
    .trim();

  // Caso venha no padrão brasileiro: 1.234,56
  if (texto.includes(',') && texto.includes('.')) {
    return Number(texto.replace(/\./g, '').replace(',', '.')) || 0;
  }

  // Caso venha com vírgula decimal: 17,90
  if (texto.includes(',')) {
    return Number(texto.replace(',', '.')) || 0;
  }

  // Caso venha com ponto decimal: 17.90
  return Number(texto) || 0;
}

const todosOsDados = items.map(item => limparChaves(item.json));

function normalizarTexto(valor) {
  return String(valor || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function temValor(valor) {
  return valor !== undefined && valor !== null && String(valor).trim() !== '';
}

// Primeiro identifica anúncios pela presença de ID/NOME ANUNCIO
const anuncios = todosOsDados.filter(item => {
  const nivel = normalizarTexto(item['NIVEL ANALISE']);

  return (
    nivel === 'anuncio' ||
    nivel === 'anuncios' ||
    temValor(item['ID ANUNCIO']) ||
    temValor(item['NOME ANUNCIO'])
  );
});

// Depois identifica conjuntos, excluindo o que já é anúncio
const conjuntos = todosOsDados.filter(item => {
  const nivel = normalizarTexto(item['NIVEL ANALISE']);

  const ehAnuncio =
    nivel === 'anuncio' ||
    nivel === 'anuncios' ||
    temValor(item['ID ANUNCIO']) ||
    temValor(item['NOME ANUNCIO']);

  return !ehAnuncio && (
    nivel === 'conjunto' ||
    nivel === 'conjuntos' ||
    temValor(item['ID CONJUNTO']) ||
    temValor(item['NOME CONJUNTO'])
  );
});

// Por último identifica campanhas
const campanhas = todosOsDados.filter(item => {
  const nivel = normalizarTexto(item['NIVEL ANALISE']);

  const ehAnuncio =
    nivel === 'anuncio' ||
    nivel === 'anuncios' ||
    temValor(item['ID ANUNCIO']) ||
    temValor(item['NOME ANUNCIO']);

  const ehConjunto =
    !ehAnuncio && (
      nivel === 'conjunto' ||
      nivel === 'conjuntos' ||
      temValor(item['ID CONJUNTO']) ||
      temValor(item['NOME CONJUNTO'])
    );

  return !ehAnuncio && !ehConjunto && (
    nivel === 'campanha' ||
    nivel === 'campanhas'
  );
});

function totais(lista) {
  const investimento = lista.reduce((soma, item) => soma + numero(item.INVESTIMENTO), 0);
  const impressoes = lista.reduce((soma, item) => soma + numero(item.IMPRESSOES), 0);
  const alcance = lista.reduce((soma, item) => soma + numero(item.ALCANCE), 0);
  const cliques = lista.reduce((soma, item) => soma + numero(item.CLIQUES), 0);
  const leads = lista.reduce((soma, item) => soma + numero(item.LEADS), 0);
  const conversas = lista.reduce((soma, item) => soma + numero(item['CONVERSAS INICIADAS']), 0);
  const cliquesLink = lista.reduce((soma, item) => soma + numero(item['CLIQUES LINK']), 0);
  const primeirasRespostas = lista.reduce((soma, item) => soma + numero(item['PRIMEIRAS RESPOSTAS']), 0);
  const conexoesMensagem = lista.reduce((soma, item) => soma + numero(item['CONEXOES MENSAGEM']), 0);
  const visualizacoesVideo = lista.reduce((soma, item) => soma + numero(item['VISUALIZAÇÕES VIDEO']), 0);

  return {
    investimento: Number(investimento.toFixed(2)),
    impressoes,
    alcance,
    cliques,
    cliques_link: cliquesLink,
    leads,
    conversas_iniciadas: conversas,
    primeiras_respostas: primeirasRespostas,
    conexoes_mensagem: conexoesMensagem,
    visualizacoes_video: visualizacoesVideo,
    cpc_medio: cliques > 0 ? Number((investimento / cliques).toFixed(2)) : null,
    cpl_medio: leads > 0 ? Number((investimento / leads).toFixed(2)) : null,
    custo_por_conversa_medio: conversas > 0 ? Number((investimento / conversas).toFixed(2)) : null,
    ctr_medio_estimado: impressoes > 0 ? Number(((cliques / impressoes) * 100).toFixed(2)) : null,
    cpm_medio_estimado: impressoes > 0 ? Number(((investimento / impressoes) * 1000).toFixed(2)) : null
  };
}

function resumirItem(item) {
  return {
    nivel_analise: item['NIVEL ANALISE'] || '',
    conta_anuncio: item['CONTA ANUNCIO'] || '',
    data_inicio: item['DATA INCIO'] || '',
    data_fim: item['DATA FIM'] || '',

    id_campanha: item['ID CAMPANHA'] || '',
    nome_campanha: item['NOME CAMPANHA'] || '',

    objetivo: item.OBJETIVO || '',
    objetivo_original: item['OBJETIVO ORIGINAL'] || '',

    id_conjunto: item['ID CONJUNTO'] || '',
    nome_conjunto: item['NOME CONJUNTO'] || item.CONJUNTO || '',

    id_anuncio: item['ID ANUNCIO'] || '',
    nome_anuncio: item['NOME ANUNCIO'] || item.ANUNCIO || '',

    investimento: numero(item.INVESTIMENTO),
    impressoes: numero(item.IMPRESSOES),
    alcance: numero(item.ALCANCE),
    cliques: numero(item.CLIQUES),
    cliques_link: numero(item['CLIQUES LINK']),
    leads: numero(item.LEADS),
    conversas_iniciadas: numero(item['CONVERSAS INICIADAS']),
    primeiras_respostas: numero(item['PRIMEIRAS RESPOSTAS']),
    conexoes_mensagem: numero(item['CONEXOES MENSAGEM']),
    visualizacoes_video: numero(item['VISUALIZAÇÕES VIDEO']),

    cpc: numero(item.CPC),
    ctr: numero(item.CTR),
    cpm: numero(item.CPM),
    cpl: numero(item.CPL),
    custo_por_conversa: numero(item['CUSTO POR CONVERSA'])
  };
}

function ordenarPorMenorCustoConversa(lista) {
  return [...lista]
    .filter(item => numero(item['CONVERSAS INICIADAS']) > 0)
    .sort((a, b) => numero(a['CUSTO POR CONVERSA']) - numero(b['CUSTO POR CONVERSA']))
    .slice(0, 5)
    .map(resumirItem);
}

function ordenarPorMaiorCustoConversa(lista) {
  return [...lista]
    .filter(item => numero(item['CONVERSAS INICIADAS']) > 0)
    .sort((a, b) => numero(b['CUSTO POR CONVERSA']) - numero(a['CUSTO POR CONVERSA']))
    .slice(0, 5)
    .map(resumirItem);
}

function ordenarPorMaiorConversas(lista) {
  return [...lista]
    .sort((a, b) => numero(b['CONVERSAS INICIADAS']) - numero(a['CONVERSAS INICIADAS']))
    .slice(0, 5)
    .map(resumirItem);
}

function ordenarPorMaiorCTR(lista) {
  return [...lista]
    .sort((a, b) => numero(b.CTR) - numero(a.CTR))
    .slice(0, 5)
    .map(resumirItem);
}

function gastoSemConversa(lista) {
  return [...lista]
    .filter(item => numero(item.INVESTIMENTO) > 0 && numero(item['CONVERSAS INICIADAS']) === 0)
    .sort((a, b) => numero(b.INVESTIMENTO) - numero(a.INVESTIMENTO))
    .slice(0, 5)
    .map(resumirItem);
}

const campanhasResumo = campanhas.map(resumirItem);
const conjuntosResumo = conjuntos.map(resumirItem);
const anunciosResumo = anuncios.map(resumirItem);

const relatorio = {
  periodo_analisado: {
    inicio: campanhasResumo[0]?.data_inicio || '',
    fim: campanhasResumo[0]?.data_fim || ''
  },

  quantidade_registros: {
    total_recebido: todosOsDados.length,
    campanhas: campanhas.length,
    conjuntos: conjuntos.length,
    anuncios: anuncios.length
  },

  totais_gerais_campanhas: totais(campanhas),

  rankings: {
    melhores_campanhas_por_custo_conversa: ordenarPorMenorCustoConversa(campanhas),
    piores_campanhas_por_custo_conversa: ordenarPorMaiorCustoConversa(campanhas),
    campanhas_com_mais_conversas: ordenarPorMaiorConversas(campanhas),
    campanhas_com_maior_ctr: ordenarPorMaiorCTR(campanhas),

    melhores_conjuntos_por_custo_conversa: ordenarPorMenorCustoConversa(conjuntos),
    piores_conjuntos_por_custo_conversa: ordenarPorMaiorCustoConversa(conjuntos),
    conjuntos_com_mais_conversas: ordenarPorMaiorConversas(conjuntos),
    conjuntos_com_maior_ctr: ordenarPorMaiorCTR(conjuntos),

    melhores_anuncios_por_custo_conversa: ordenarPorMenorCustoConversa(anuncios),
    piores_anuncios_por_custo_conversa: ordenarPorMaiorCustoConversa(anuncios),
    anuncios_com_mais_conversas: ordenarPorMaiorConversas(anuncios),
    anuncios_com_maior_ctr: ordenarPorMaiorCTR(anuncios)
  },

  alertas_numericos: {
    campanhas_com_gasto_sem_conversa: gastoSemConversa(campanhas),
    conjuntos_com_gasto_sem_conversa: gastoSemConversa(conjuntos),
    anuncios_com_gasto_sem_conversa: gastoSemConversa(anuncios)
  },

  dados_para_analise: {
    campanhas: campanhasResumo,
    conjuntos: conjuntosResumo,
    anuncios: anunciosResumo
  }
};

return [
  {
    json: {
      relatorio_meta_ads: relatorio,
      texto_para_ia: JSON.stringify(relatorio, null, 2)
    }
  }
];

const relatorioOriginal = $json.output || $json.text || $json.relatorio || '';

if (!relatorioOriginal) {
  return [
    {
      json: {
        erro: true,
        mensagem: 'Nenhum relatório encontrado no campo output.'
      }
    }
  ];
}

function limparMarkdown(texto) {
  return texto
    .replace(/---/g, '')
    .replace(/\*\*/g, '*')
    .replace(/### /g, '')
    .replace(/## /g, '')
    .replace(/# /g, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function quebrarPorTamanho(texto, limite = 2800) {
  const partes = [];
  let atual = '';

  const blocos = texto.split('\n\n');

  for (const bloco of blocos) {
    if ((atual + '\n\n' + bloco).length <= limite) {
      atual += atual ? '\n\n' + bloco : bloco;
    } else {
      if (atual) partes.push(atual.trim());

      if (bloco.length > limite) {
        const frases = bloco.split('. ');
        let parteLonga = '';

        for (const frase of frases) {
          const trecho = frase.endsWith('.') ? frase : frase + '.';

          if ((parteLonga + ' ' + trecho).length <= limite) {
            parteLonga += parteLonga ? ' ' + trecho : trecho;
          } else {
            if (parteLonga) partes.push(parteLonga.trim());
            parteLonga = trecho;
          }
        }

        if (parteLonga) partes.push(parteLonga.trim());
        atual = '';
      } else {
        atual = bloco;
      }
    }
  }

  if (atual) partes.push(atual.trim());

  return partes;
}

const relatorioLimpo = limparMarkdown(relatorioOriginal);

const cabecalho = `RELATÓRIO META ADS

Análise automática de performance, desperdício de verba, oportunidades de melhoria e sugestões de novos anúncios.

`;

const relatorioComCabecalho = cabecalho + relatorioLimpo;

const mensagens = quebrarPorTamanho(relatorioComCabecalho, 2800);

return mensagens.map((mensagem, index) => {
  return {
    json: {
      parte: index + 1,
      total_partes: mensagens.length,
      mensagem_envio: mensagens.length > 1
        ? `Parte ${index + 1}/${mensagens.length}\n\n${mensagem}`
        : mensagem
    }
  };
});
